(()=>{'use strict';
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#site-nav');
function closeMenu(){nav?.classList.remove('is-open');menu?.setAttribute('aria-expanded','false')}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});
nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(nav?.classList.contains('is-open')){closeMenu();menu.focus()}}});addEventListener('resize',()=>{if(innerWidth>760)closeMenu()});
const legacy={work:'/work/',about:'/about/',contact:'/contact/','case-camfire':'/work/camfire/','case-remic':'/work/remic/','case-minimalance':'/work/minimalance/','case-xipster':'/work/xipster/','case-radhe':'/lab/radhe-dhokla/','project-experiments':'/lab/'};
if(location.pathname==='/'&&legacy[location.hash.slice(1)])location.replace(legacy[location.hash.slice(1)]);
let scrollPending=false;const progress=document.querySelector('.scroll-progress');function updateProgress(){const height=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${height>0?Math.min(1,Math.max(0,scrollY/height)):0})`;scrollPending=false}addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(updateProgress)}},{passive:true});updateProgress();
if(matchMedia('(hover:hover) and (pointer:fine)').matches){document.querySelectorAll('[data-tilt]').forEach(el=>{el.addEventListener('pointermove',e=>{if(reduced.matches)return;const r=el.getBoundingClientRect();el.style.transform=`perspective(1000px) rotateX(${-(e.clientY-r.top-r.height/2)/r.height*3}deg) rotateY(${(e.clientX-r.left-r.width/2)/r.width*3}deg)`});el.addEventListener('pointerleave',()=>el.style.transform='')})}
const hero=document.querySelector('video[data-hero]');if(hero){const play=document.querySelector('[data-play]');let pausedByUser=false;const setLabel=()=>play.textContent=hero.paused?'Play reel':'Pause reel';hero.addEventListener('play',setLabel);hero.addEventListener('pause',setLabel);play.addEventListener('click',()=>{if(hero.paused){pausedByUser=false;hero.play().catch(()=>setLabel())}else{pausedByUser=true;hero.pause()}});new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting&&!reduced.matches&&!pausedByUser&&!document.hidden)hero.play().catch(()=>setLabel());else hero.pause()})},{threshold:.4}).observe(hero);reduced.addEventListener('change',()=>{if(reduced.matches)hero.pause()})}
document.querySelectorAll('video').forEach(video=>video.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==video)other.pause()})));document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause())});
const dialog=document.querySelector('.lightbox');let previousFocus;document.querySelectorAll('[data-enlarge]').forEach(button=>button.addEventListener('click',()=>{previousFocus=button;const img=dialog.querySelector('img');img.src='/assets/'+button.dataset.enlarge;img.alt=button.dataset.caption;dialog.querySelector('[data-lightbox-label]').textContent=button.dataset.caption;dialog.showModal()}));dialog?.querySelector('[data-lightbox-close]').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog?.addEventListener('close',()=>previousFocus?.focus());
const canvas=document.querySelector('[data-signal-field]');if(canvas){const ctx=canvas.getContext('2d');let width=230,height=230,visible=false,frame=0,offset={x:0,y:0};function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}function draw(time){ctx.clearRect(0,0,width,height);const t=reduced.matches?0:time*.00018;for(let i=0;i<72;i++){const angle=i/72*Math.PI*2+t;const ring=(i%3)*16+width*.28;const x=width/2+Math.cos(angle)*ring+offset.x,y=height/2+Math.sin(angle)*ring+offset.y;ctx.save();ctx.translate(x,y);ctx.rotate(angle+t);ctx.fillStyle=i%4===0?'#ff6b36':i%3===0?'#b6a4d2':'#b9c8a4';ctx.globalAlpha=.55+(i%4)*.1;const size=i%8===0?8:3;ctx.fillRect(-size/2,-size/2,size,size);ctx.restore()}if(visible&&!document.hidden&&!reduced.matches)frame=requestAnimationFrame(draw);else frame=0}function start(){if(!frame){frame=requestAnimationFrame(draw)}}new ResizeObserver(()=>{resize();if(reduced.matches||!visible)draw(0)}).observe(canvas);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)start();else{cancelAnimationFrame(frame);frame=0}},{threshold:.05}).observe(canvas);reduced.addEventListener('change',()=>{cancelAnimationFrame(frame);frame=0;draw(0)});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0}else if(visible)start()});canvas.parentElement.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();offset.x=(e.clientX-r.left-width/2)*.025;offset.y=(e.clientY-r.top-height/2)*.025});canvas.parentElement.addEventListener('pointerleave',()=>offset={x:0,y:0});resize();draw(0)}
})();
